SELECT 'TOTAL' AS k, count(*)::text AS v FROM ai_ro.public__permissions UNION ALL SELECT 'NEW_EXISTING', count(*)::text FROM ai_ro.public__permissions WHERE key LIKE 'leads.discord%' UNION ALL SELECT 'MAX_ID', max(id)::text FROM ai_ro.public__permissions UNION ALL SELECT 'T001_UPD', count(*)::text FROM ai_ro.tenant_001__role_permissions WHERE permission_id = 14 UNION ALL SELECT 'T001_DEL', count(*)::text FROM ai_ro.tenant_001__role_permissions WHERE permission_id = 15 UNION ALL SELECT 'T003_UPD', count(*)::text FROM ai_ro.tenant_003__role_permissions WHERE permission_id = 14 UNION ALL SELECT 'T003_DEL', count(*)::text FROM ai_ro.tenant_003__role_permissions WHERE permission_id = 15 UNION ALL SELECT 'T004_UPD', count(*)::text FROM ai_ro.tenant_004__role_permissions WHERE permission_id = 14 UNION ALL SELECT 'T004_DEL', count(*)::text FROM ai_ro.tenant_004__role_permissions WHERE permission_id = 15 UNION ALL SELECT 'T005_UPD', count(*)::text FROM ai_ro.tenant_005__role_permissions WHERE permission_id = 14 UNION ALL SELECT 'T005_DEL', count(*)::text FROM ai_ro.tenant_005__role_permissions WHERE permission_id = 15 UNION ALL SELECT 'T006_UPD', count(*)::text FROM ai_ro.tenant_006__role_permissions WHERE permission_id = 14 UNION ALL SELECT 'T006_DEL', count(*)::text FROM ai_ro.tenant_006__role_permissions WHERE permission_id = 15 UNION ALL SELECT 'TENANTS', string_agg(id::text || ':' || tenant_code || ':' || is_active::text, ' ' ORDER BY id) FROM ai_ro.public__tenants;
